                s_list[i] = str(int(s_list[i]) + 1)
                for j in range(i+1, left_end+1):
                    s_list[j] = '0'
                break
            else:
                s_list[i] = '0'
                i -= 1
        else:
            # All left half digits were 9, so we need to handle carry over
