def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x] = number of sequences of length i starting with element x
    # Condition: next element >= 2 * previous element
    # First element can be any integer from 1 to m

    if n == 1:
        return m  # any element from 1 to m

    dp = [0] * (m + 2)  # 1-based indexing
    # Base case: sequences of length 1 starting with x = 1 for all x in [1..m]
    for x in range(1, m + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 2)
        # To efficiently calculate sum of dp[y] for y >= 2*x,
        # precompute suffix sums of dp
        suffix_sum = [0] * (m + 3)
        for i in range(m, 0, -1):
            suffix_sum[i] = suffix_sum[i + 1] + dp[i]
        for x in range(1, m + 1):
            min_next = 2 * x
            if min_next <= m:
                new_dp[x] = suffix_sum[min_next]
            else:
                new_dp[x] = 0
        dp = new_dp

    return sum(dp[1:m+1])

