    if start == end:
        return arr[start]

    # If subarray is already sorted, return the last element
    if arr[start] < arr[end]:
        return arr[end]

    mid = (start + end) // 2

    # If mid element is greater than its next element, mid is max
    if mid < end and arr[mid] > arr[mid + 1]:
        return arr[mid]

    # If mid element is smaller than its previous element, mid-1 is max
    if mid > start and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # Decide which side to search
