def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Handle single digit numbers:
    # The next smallest palindrome less than num is num-1 if num>0, else -1 (no palindrome < 0)
    if length == 1:
        return num - 1 if num > 0 else -1

    def is_all_zeros(s):
        return all(ch == '0' for ch in s)

    # For numbers like 1000, 10000 etc., the next smaller palindrome is 999...9 (length-1 times)
    # General approach when palindrome less than num has fewer digits:
    # For example, next smallest palindrome less than 1000 is 999.

    # If the number is of the form 10...0, next smallest palindrome is 9...9 (length-1 times)
    if s[0] == '1' and is_all_zeros(s[1:]):
        return int('9' * (length - 1))

    # Helper to check if a string is palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Construct palindrome by mirroring left half onto right half
    def make_palindrome(left: str, length: int) -> str:
        if length % 2 == 0:
            return left + left[::-1]
        else:
            return left + left[-2::-1]

    # We try to build a palindrome smaller than num.
    # Steps:
    # 1. Take left half (including middle if odd length)
    # 2. Mirror it to form palindrome
    # 3. If palindrome < num, return it
    # 4. Else decrement the left half (as a number) and mirror again
    # 5. If decremented left half becomes shorter (like 100 -> 99), then answer is 9...9 of length-1

    half_len = (length + 1) // 2
    left_half = s[:half_len]
    pal_candidate = make_palindrome(left_half, length)

    if int(pal_candidate) < num:
        return int(pal_candidate)

    # Decrement the left half as an integer and then make palindrome again
    left_num = int(left_half) - 1
    if left_num == 0:
        # This happens if left_half was 1 and we decremented to 0
        # For example, num=101 -> left_half=10 (for odd length=3 half_len=2)
        # Actually for odd length 3, half_len=2, left_half='10', after decrement left_num=9
        # So 0 only if left_half was '1'
        return int('9'*(length-1))

    left_str = str(left_num)

    # If after decrement length of left_str is less than half_len, it means we lost a digit
    # e.g. left_half='100' -> after decrement 99, length shorter
    # then answer is 9...9 of length-1
    if len(left_str) < half_len:
        return int('9'*(length-1))

    pal_candidate = make_palindrome(left_str, length)
    return int(pal_candidate)

