def find_Max(seq):
    if not seq:
        raise ValueError("Empty sequence has no maximum")
    left, right = 0, len(seq) - 1
    # If the sequence is not rotated (fully sorted ascending), max is last element
    if seq[left] < seq[right]:
        return seq[right]
    # Binary search for rotation point which is max
    while left < right:
        mid = (left + right) // 2
        if seq[mid] > seq[right]:
            left = mid + 1
        else:
            right = mid
    # left now points to the smallest element, max is element before it
    return seq[left - 1] if left > 0 else seq[-1]

