def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x]: number of sequences of length i ending with element x
    # Elements are in [1..m]
    if n == 1:
        return m  # any element from 1 to m

    dp_prev = [1] * (m + 1)  # for sequences of length 1, dp_prev[x] = 1 for x in [1..m]

    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        # To compute dp_curr[x], sum dp_prev[y] for all y where:
        # x >= 2*y and x <= m
        # For fixed x, y must satisfy y <= x//2
        # So dp_curr[x] = sum of dp_prev[y] for y in [1..x//2]
        prefix_sum = 0
        # precompute prefix sums of dp_prev to quickly sum up dp_prev[1..k]
        prefix_dp = [0] * (m + 1)
        for i in range(1, m + 1):
            prefix_dp[i] = prefix_dp[i - 1] + dp_prev[i]

        for x in range(1, m + 1):
            limit = x // 2
            if limit >= 1:
                dp_curr[x] = prefix_dp[limit]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr

    return sum(dp_prev[1:])

