def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x]: number of sequences of length i ending with element x
    # i ranges from 1 to n
    # x ranges from 1 to m

    if n == 1:
        return m

    dp = [0] * (m + 1)
    # For sequences of length 1, count is 1 for each element 1..m
    for x in range(1, m + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # For each possible next element y, sum over all x where y >= 2*x
        # That is, for each y, sum dp[x] for all x with x <= y//2
        # Precompute prefix sums of dp to optimize
        prefix = [0] * (m + 2)
        for i in range(1, m + 1):
            prefix[i] = prefix[i - 1] + dp[i]

        for y in range(1, m + 1):
            max_x = y // 2
            if max_x >= 1:
                new_dp[y] = prefix[max_x]
            else:
                new_dp[y] = 0

        dp = new_dp

    return sum(dp[1:])  # sum over sequences of length n ending with any valid element

